  const fountain=asset("fountain","石泉水池","Standalone village drinking fountain, low octagonal stone basin with central carved spout and visible contained water, worn rim, no surrounding ground, no background or text.",[3.2,2.3,3.2],1);
  const bench=asset("bench","公共长凳","Standalone sturdy weathered timber village bench on stone legs, seating faces Z+, no ground or background.",[2.4,1,0.75],1);
  const lamp=asset("street-lantern","街巷灯柱","Standalone functional village lantern on a slender wrought iron post, enclosed warm glass lantern at top, stone mounting foot, no ground or background.",[0.55,3.5,0.55],1,{kind:"point",color:"#FFD69A",intensity:1.6,range:7,offset:[0,3.1,0]});
  const cart=asset("handcart","木车货筐","Standalone parked wooden handcart with two wheels, shafts facing Z+, several sacks and wicker baskets secured in its bed, no ground or background.",[1.6,1.5,2.8],1);
  const wood=asset("woodpile","柴薪架","Standalone compact covered firewood rack with neatly stacked split logs beneath a small slate shelter, opening on Z+, no ground or background.",[2.2,1.9,1.1],1);
  const pots=asset("door-pots","门边花盆","Standalone pair of rustic terracotta pots with herbs and small flowers, no ground, background or text.",[0.85,0.8,0.6],1);
  function natural(key,name,prompt,dimensions,variants) {
    return api.requireAsset({key:key,name:name,prompt:prompt+orientation,dimensions:dimensions,variants:variants,role:"environment"});
  }
  const tree=natural("valley-trees","山谷乔木","Standalone mountain deciduous tree, irregular branching, full restrained crown with clear trunk, no ground or background.",[6,11,6],2);
  const pine=natural("ridge-pine","山坡松树","Standalone mature mountain pine, weathered trunk, asymmetrical layered needles, no ground or background.",[5,12,5],1);
  const rock=natural("outcrop","山坡岩块","Standalone irregular fractured mountain rock outcrop with subtle lichen and moss in crevices, no ground or background.",[4,3,3.5],2);

  function road(id,points,width,material) {
    for(let i=0;i<points.length-1;i++) {
      api.rampTerrain({start:points[i],end:points[i+1],width:width+0.8,softness:0.8,strength:1});
    }
    return api.route({id:id,points:points,width:width,curve:"polyline",surface:"paving",material:material || "cobblestone"});
  }

  const alternatives=[
    {left:-16,right:16,bend:1.5},
    {left:-17.5,right:17.5,bend:0},
    {left:-15,right:15,bend:-1.5}
  ];
  let chosen=alternatives[0],best=100000;
  for(const arrangement of alternatives) {
    let score=0;
    for(const z of [-34,-23,-12,-1,10,21]) {
      for(const x of [arrangement.left,0,arrangement.right]) {
        const sample=api.environmentSample([x,z]);
        score+=sample.slope+Math.abs(sample.height)*0.025;
