    }
    if(score<best) {best=score;chosen=arrangement;}
  }
  const left=chosen.left,right=chosen.right;
  road("entry-spine",[[0,-46],[-1,-36],[0,-25],[chosen.bend,-13],[0,0],[0,12],[0,24]],4.2);
