  for(const z of [-35,-24,-12,0]) {
    road("cross-"+z,[[left,z],[0,z],[right,z]],2.7);
  }
  road("upper-walk",[[left,13],[-10,13],[0,13],[10,13],[right,13]],3);
  road("chapel-path",[[left,13],[left-7,13],[left-11,19],[left-11,22]],2.5);

  const squareHeight=api.environmentSample([0,19]).height;
  api.sculptTerrain({mode:"flatten",point:[0,19],radius:9.5,strength:0.85,targetHeight:squareHeight});
  api.sculptTerrain({mode:"smooth",point:[0,19],radius:12,strength:0.5});
  api.environmentSample([0,19]);
  api.surface({id:"assembly-square",surface:"paving",material:"garden-stone",region:{kind:"polygon",points:[[-8,12],[8,12],[9,23],[6,25],[-6,25],[-9,23]]},clearNatural:true});
  road("square-axis",[[0,12],[0,19],[0,24],[0,26]],3.5);
  road("square-west-link",[[left,13],[-8,15],[0,15]],2.7);
  road("square-east-link",[[right,13],[8,15],[0,15]],2.7);

  let homeIndex=0;
  for(const side of [-1,1]) {
    const lane=side<0?left:right;
    for(const row of [-29.5,-18,-6,6.5]) {
      for(const outer of [false,true]) {
        const nominalX=lane+(outer?side*7.1:-side*7.1);
        const candidates=[[nominalX,row],[nominalX,row+0.7],[nominalX+side*0.65,row-0.4]];
        let site=candidates[0],siteScore=100000;
        for(const p of candidates) {
          const center=api.environmentSample(p);
          let minimum=center.height,maximum=center.height;
          for(const dx of [-3.3,3.3]) {
            for(const dz of [-3.3,3.3]) {
              const h=api.environmentSample([p[0]+dx,p[1]+dz]).height;
              minimum=Math.min(minimum,h);
              maximum=Math.max(maximum,h);
            }
          }
          const score=maximum-minimum+center.slope*0.04;
          if(score<siteScore) {site=p;siteScore=score;}
        }
        const target=[lane,site[1]];
        const direction=lane>site[0]?1:-1;
        const door=[site[0]+direction*3.2,site[1]];
        const level=api.environmentSample(site).height;
        api.sculptTerrain({mode:"flatten",point:site,radius:4.5,strength:0.8,targetHeight:level});
